import React, { useEffect, useRef, useState } from "react";
import { Html5Qrcode } from "html5-qrcode";

function QRScanner() {
  const [isScanning, setIsScanning] = useState(false);
  const [status, setStatus] = useState("");
  const [student, setStudent] = useState(null);
  const scannerRef = useRef(null);
  const isProcessing = useRef(false);

  useEffect(() => {
    // 1. Initialize scanner
    scannerRef.current = new Html5Qrcode("reader");
    return () => {
      if (scannerRef.current?.isScanning) {
        scannerRef.current.stop().catch(() => {});
      }
    };
  }, []);

  const startScanner = async () => {
    try {
      setStatus("");
      setStudent(null);

      // 2. Strict Configuration to prevent "Black Screen" initialization errors
      await scannerRef.current.start(
        { facingMode: "environment" },
        {
          fps: 10,
          qrbox: { width: 250, height: 250 },
          aspectRatio: 1.0,
        },
        onScanSuccess,
      );
      setIsScanning(true);
    } catch (err) {
      console.error("Camera Error:", err);
      alert(
        "Camera Access Denied or Busy. Check browser permissions (camera icon in address bar).",
      );
    }
  };

  const stopScanner = async () => {
    if (scannerRef.current?.isScanning) {
      await scannerRef.current.stop();
      setIsScanning(false);
    }
  };

  const onScanSuccess = async (decodedText) => {
    if (isProcessing.current) return;
    isProcessing.current = true;

    try {
      const response = await fetch(
        `http://localhost:5000/verify-user/${decodedText}`,
      );
      const data = await response.json();

      if (data.success) {
        setStudent(data.user);

        // Mark attendance
        const attendance = await fetch(
          `http://localhost:5000/mark-attendance/${decodedText}`,
          { method: "PUT" },
        );
        const attData = await attendance.json();
        setStatus(attData.success ? "success" : "already");
      } else {
        setStatus("notfound");
      }
    } catch (err) {
      setStatus("error");
    } finally {
      setTimeout(() => {
        isProcessing.current = false;
      }, 3000);
    }
  };

  return (
    <div
      style={{ textAlign: "center", padding: "20px", fontFamily: "sans-serif" }}
    >
      <h2>Event Attendance Scanner</h2>

      {/* Reader Container - Styled to prevent collapse */}
      <div
        id="reader"
        style={{
          width: "100%",
          maxWidth: "400px",
          margin: "auto",
          backgroundColor: "#000",
          minHeight: "300px",
          borderRadius: "15px",
          overflow: "hidden",
        }}
      />

      <div style={{ marginTop: "20px" }}>
        {!isScanning ? (
          <button onClick={startScanner} style={btnStyle("#28a745")}>
            Start Camera
          </button>
        ) : (
          <button onClick={stopScanner} style={btnStyle("#dc3545")}>
            Stop Camera
          </button>
        )}
      </div>

      {/* Result Display Area */}
      <div style={{ marginTop: "20px", minHeight: "100px" }}>
        {student && (
          <div style={cardStyle}>
            <h3>{student.name}</h3>
            <p>Event: {student.event_name || "N/A"}</p>
            {status === "success" && (
              <p style={{ color: "green" }}>✔ Attendance Marked</p>
            )}
            {status === "already" && (
              <p style={{ color: "orange" }}>⚠️ Already Scanned</p>
            )}
          </div>
        )}
        {status === "notfound" && (
          <p style={{ color: "red" }}>❌ Student Not Registered</p>
        )}
      </div>
    </div>
  );
}

// Helper Styles
const btnStyle = (color) => ({
  padding: "12px 24px",
  color: "white",
  backgroundColor: color,
  border: "none",
  borderRadius: "5px",
  cursor: "pointer",
  fontSize: "16px",
});

const cardStyle = {
  border: "1px solid #ccc",
  padding: "15px",
  borderRadius: "10px",
  maxWidth: "400px",
  margin: "auto",
  backgroundColor: "#f9f9f9",
};

export default QRScanner;
